-- Additive conquest server v1. Prepared for review; no operating deployment is implied.
-- No catalog/team/start seed, scheduler, client activation or destructive rollback.
-- Generated by supabase/conquest/build-release.mjs; normalized-LF source SHA256:
-- ledger: 56c98c41a7f571b377fbfb78f838a43ce36c26a3e4459b0f414bce618678712a
-- proof: 9c77b43d7e6210ac1a61af6eacdf2237edd76d7fb95882f7b6f114d252e24ec4
-- gateway: fd2070e6d0c6f525b408817c73e730e7f82957c67f64543ab76fb4370180024e
-- settlement: ea825fb6ae45e95c4b28c9ae37346cb1827daf482af111c9c25907247b6bf133
-- intake: 6b7c5eda4845919f97e134a55c4cfe0610ba753e493cdf3b95eb00cc52ad6083
begin;
do $$ begin
    if to_regclass('auth.users') is null or to_regprocedure('auth.uid()') is null
      or to_regtype('extensions.geometry') is null then raise exception 'Auth and existing extensions PostGIS required';end if;
    if to_regclass('public.conquest_road_catalog') is null or to_regclass('public.conquest_ownership') is null
      then raise exception 'Existing shared reserved tables required';end if;
    if to_regnamespace('conquest_internal') is not null then raise exception 'Existing conquest installation needs explicit upgrade';end if;
    if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in
      ('conquest_submit_v1','conquest_select_team_v1','conquest_membership_v1','conquest_snapshot_v1'))
      then raise exception 'Public conquest RPC collision';end if;
  end $$;

-- ledger
create schema conquest_internal;
revoke all on schema conquest_internal from public, anon, authenticated;

create table conquest_internal.teams (id text primary key check(length(id) between 1 and 100));
create table conquest_internal.catalogs (version text primary key);
create table conquest_internal.roads (
  catalog text references conquest_internal.catalogs(version),
  id text not null,
  primary key(catalog,id)
);
create table conquest_internal.worlds (
  partition text primary key check(partition in ('pleos','pleos-emulator')),
  catalog text not null references conquest_internal.catalogs(version)
);
create table conquest_internal.memberships (
  user_id uuid references auth.users(id),
  partition text references conquest_internal.worlds(partition),
  team_id text not null references conquest_internal.teams(id),
  selected_ms bigint not null check(selected_ms>=0),
  primary key(user_id,partition)
);
create table conquest_internal.receipts (
  user_id uuid references auth.users(id),
  partition text references conquest_internal.worlds(partition),
  event_id text check(length(event_id) between 1 and 200),
  payload jsonb not null,
  outcome jsonb not null,
  admitted_ms bigint not null check(admitted_ms>=0),
  primary key(user_id,partition,event_id)
);
create table conquest_internal.contributions (
  user_id uuid not null,
  partition text not null,
  event_id text not null,
  catalog text not null,
  road_id text not null,
  game_date date not null,
  afternoon boolean not null,
  occurred_ms bigint not null check(occurred_ms>=0),
  team_id text not null references conquest_internal.teams(id),
  primary key(user_id,partition,catalog,road_id,game_date,afternoon),
  unique(user_id,partition,event_id),
  foreign key(user_id,partition,event_id) references conquest_internal.receipts(user_id,partition,event_id),
  foreign key(catalog,road_id) references conquest_internal.roads(catalog,id)
);
create index conquest_window on conquest_internal.contributions(partition,catalog,occurred_ms,road_id,team_id);

-- All functions are SECURITY INVOKER, schema-private, and not executable by client roles.
-- Timestamps and user IDs are trusted test/verifier inputs, never request authorization.
create function conquest_internal.select_team(
  p_user uuid,p_partition text,p_team text,p_selected_ms bigint
) returns text language plpgsql set search_path='' as $$
declare old_team text;
begin
  if p_user is null or p_team is null or length(p_team) not between 1 and 100
    or p_selected_ms is null or p_selected_ms<0 then raise exception 'Invalid team input'; end if;
  perform 1 from conquest_internal.worlds where partition=p_partition for update;
  if not found then raise exception 'Invalid partition'; end if;
  select team_id into old_team from conquest_internal.memberships where user_id=p_user and partition=p_partition;
  if found then return case when old_team=p_team then 'UNCHANGED' else 'TEAM_LOCKED' end; end if;
  insert into conquest_internal.memberships values(p_user,p_partition,p_team,p_selected_ms);
  return 'SELECTED';
end $$;

create function conquest_internal.accept_verified(
  p_user uuid,p_partition text,p_catalog text,p_event text,p_road text,
  p_occurred_ms bigint,p_proof_hash text,p_detector text,p_admitted_ms bigint
) returns jsonb language plpgsql set search_path='' as $$
declare
  active_catalog text; canonical jsonb; prior conquest_internal.receipts%rowtype;
  membership conquest_internal.memberships%rowtype; result_code text; result jsonb;
  local_time timestamp; noon timestamp; cutoff_ms bigint; admitted_ms bigint;
begin
  if p_user is null or p_event is null or length(p_event) not between 1 and 200
    or p_catalog is null or p_road is null or length(p_road)=0
    or p_occurred_ms is null or p_occurred_ms<0 or (p_admitted_ms is null or p_admitted_ms<0)
    or p_proof_hash is null or p_proof_hash !~ '^[a-f0-9]{64}$'
    or p_detector is null or length(p_detector) not between 1 and 100 then raise exception 'Invalid verified input'; end if;
  select catalog into active_catalog from conquest_internal.worlds where partition=p_partition for update;
  if not found then raise exception 'Invalid partition'; end if;
  -- Admission time comes only from the private gateway after acquiring the world lock.
  admitted_ms:=p_admitted_ms;
  canonical:=jsonb_build_object('catalog',p_catalog,'road',p_road,'occurred_ms',p_occurred_ms,
    'proof_hash',p_proof_hash,'detector',p_detector);
  select * into prior from conquest_internal.receipts
    where user_id=p_user and partition=p_partition and event_id=p_event;
  if found then
    if prior.payload<>canonical then return jsonb_build_object('eventId',p_event,'status','CONFLICT'); end if;
    return prior.outcome;
  end if;
  -- A future timestamp is retryable: do not permanently poison the event receipt.
  if p_occurred_ms>admitted_ms then return jsonb_build_object('eventId',p_event,'status','FUTURE'); end if;
  local_time:=to_timestamp(admitted_ms/1000.0) at time zone 'Asia/Seoul';
  noon:=date_trunc('day',local_time)+interval '12 hours';
  if local_time<noon then noon:=noon-interval '1 day'; end if;
  cutoff_ms:=(extract(epoch from (noon at time zone 'Asia/Seoul'))*1000)::bigint;
  select * into membership from conquest_internal.memberships where user_id=p_user and partition=p_partition;
  result_code:=case
    when active_catalog<>p_catalog then 'WRONG_CATALOG'
    when not exists(select 1 from conquest_internal.roads where catalog=p_catalog and id=p_road) then 'UNKNOWN_ROAD'
    when membership.team_id is null then 'NO_TEAM'
    when p_occurred_ms<membership.selected_ms then 'BEFORE_TEAM_SELECTION'
    when p_occurred_ms<cutoff_ms then 'LATE'
    else 'ACCEPTED' end;
  local_time:=to_timestamp(p_occurred_ms/1000.0) at time zone 'Asia/Seoul';
  if result_code='ACCEPTED' and exists(select 1 from conquest_internal.contributions
    where user_id=p_user and partition=p_partition and catalog=p_catalog and road_id=p_road
      and game_date=local_time::date and afternoon=(extract(hour from local_time)>=12)) then
    result_code:='DUPLICATE_HALF_DAY';
  end if;
  result:=jsonb_build_object('eventId',p_event,'status',result_code);
  insert into conquest_internal.receipts values(p_user,p_partition,p_event,canonical,result,admitted_ms);
  if result_code='ACCEPTED' then
    insert into conquest_internal.contributions values(p_user,p_partition,p_event,p_catalog,p_road,
      local_time::date,extract(hour from local_time)>=12,p_occurred_ms,membership.team_id);
  end if;
  return result;
end $$;

alter table conquest_internal.teams enable row level security;
alter table conquest_internal.catalogs enable row level security;
alter table conquest_internal.roads enable row level security;
alter table conquest_internal.worlds enable row level security;
alter table conquest_internal.memberships enable row level security;
alter table conquest_internal.receipts enable row level security;
alter table conquest_internal.contributions enable row level security;
revoke all on all tables in schema conquest_internal from public,anon,authenticated;
revoke all on all functions in schema conquest_internal from public,anon,authenticated;

-- proof
create table conquest_internal.road_geometry (
  catalog text not null, road_id text not null, ordinal integer not null check(ordinal>=0),
  path extensions.geometry(LineString,4326) not null,
  primary key(catalog,road_id), unique(catalog,ordinal),
  foreign key(catalog,road_id) references conquest_internal.roads(catalog,id),
  check(extensions.st_npoints(path)>=2 and not extensions.st_isempty(path))
);
create index conquest_geometry on conquest_internal.road_geometry using gist(path);
alter table conquest_internal.road_geometry enable row level security;
revoke all on conquest_internal.road_geometry from public,anon,authenticated;

-- Same road-local equirectangular projection and 30m endpoint extensions as DirectedRoad.
create function conquest_internal.locate(p_path extensions.geometry,p_lat double precision,p_lon double precision)
returns table(distance_m double precision,progress_m double precision,length_m double precision)
language plpgsql immutable set search_path='' as $$
declare
  origin extensions.geometry:=extensions.st_startpoint(p_path);
  sx double precision:=pi()/180*6371008.8*cos(radians(extensions.st_y(origin)));
  sy double precision:=pi()/180*6371008.8;
  px double precision:=(p_lon-extensions.st_x(origin))*sx;
  py double precision:=(p_lat-extensions.st_y(origin))*sy;
  a extensions.geometry; b extensions.geometry; ax double precision; ay double precision;
  dx double precision; dy double precision; len double precision; raw double precision; t double precision;
  d double precision; travelled double precision:=0; i integer; n integer:=extensions.st_npoints(p_path);
begin
  distance_m:='Infinity'::double precision; progress_m:=0;
  for i in 1..n-1 loop
    a:=extensions.st_pointn(p_path,i); b:=extensions.st_pointn(p_path,i+1);
    ax:=(extensions.st_x(a)-extensions.st_x(origin))*sx;
    ay:=(extensions.st_y(a)-extensions.st_y(origin))*sy;
    dx:=(extensions.st_x(b)-extensions.st_x(a))*sx;
    dy:=(extensions.st_y(b)-extensions.st_y(a))*sy;
    len:=sqrt(dx*dx+dy*dy);
    if len<=0 then raise exception 'Degenerate catalog geometry'; end if;
    raw:=((px-ax)*dx+(py-ay)*dy)/(len*len);
    t:=case when i=1 and raw<0 then greatest(raw,-30/len)
      when i=n-1 and raw>1 then least(raw,1+30/len) else greatest(0,least(raw,1)) end;
    d:=sqrt(power(px-ax-t*dx,2)+power(py-ay-t*dy,2));
    if d<distance_m then distance_m:=d;progress_m:=travelled+t*len;end if;
    travelled:=travelled+len;
  end loop;
  if travelled<50 then raise exception 'Catalog road shorter than 50m'; end if;
  length_m:=travelled;return next;
end $$;

-- Replay only. Defaults mirror DirectedRoadDetector; this version has no persistent trip cursor.
create function conquest_internal.replay_proof(p_catalog text,p_samples jsonb)
returns jsonb language plpgsql stable set search_path='' as $$
declare
  sample jsonb; previous jsonb; trips jsonb:='{}'; next_trips jsonb; trip jsonb;
  completions jsonb:='[]'; completed text[]; road conquest_internal.road_geometry%rowtype;
  lat double precision; lon double precision; acc double precision; tm bigint; eid text;
  old_lat double precision; old_lon double precision; old_tm bigint; step_sx double precision;
  sy constant double precision:=pi()/180*6371008.8; step_m double precision;
  pos record; sx double precision; exit_m double precision; observations integer;
  reached boolean; max_progress double precision;
begin
  -- Technical bound for isolated tests, not an approved device queue/proof size policy.
  if p_samples is null or jsonb_typeof(p_samples)<>'array' or jsonb_array_length(p_samples) not between 3 and 2048
    then raise exception 'Invalid proof batch';end if;
  if (select count(*) from conquest_internal.road_geometry where catalog=p_catalog)=0 or
    (select count(*) from conquest_internal.road_geometry where catalog=p_catalog)<>
    (select count(*) from conquest_internal.roads where catalog=p_catalog)
    then raise exception 'Incomplete catalog geometry';end if;
  select pi()/180*6371008.8*cos(radians(extensions.st_y(extensions.st_startpoint(path)))) into step_sx
    from conquest_internal.road_geometry where catalog=p_catalog order by ordinal limit 1;
  for sample in select value from jsonb_array_elements(p_samples) loop
    if previous=sample then continue;end if;
    if jsonb_typeof(sample)<>'object' or jsonb_typeof(sample->'id') is distinct from 'string'
      or jsonb_typeof(sample->'time') is distinct from 'number'
      or jsonb_typeof(sample->'lat') is distinct from 'number'
      or jsonb_typeof(sample->'lon') is distinct from 'number'
      or jsonb_typeof(sample->'accuracy') is distinct from 'number'
      then trips:='{}';continue;end if;
    eid:=sample->>'id';lat:=(sample->>'lat')::double precision;lon:=(sample->>'lon')::double precision;
    acc:=(sample->>'accuracy')::real::double precision;
    if (sample->>'time')::numeric<>trunc((sample->>'time')::numeric) then trips:='{}';continue;end if;
    tm:=(sample->>'time')::bigint;
    if length(eid) not between 1 and 200 or length(btrim(eid))=0 or tm<0 or lat not between -80 and 80 or lon not between -180 and 180
      or acc not between 0 and 10 or (previous is not null and tm<=old_tm)
      then trips:='{}';continue;end if;
    if previous is not null then
      step_m:=sqrt(power((lon-old_lon)*step_sx,2)+power((lat-old_lat)*sy,2));
    end if;
    previous:=sample;
    if old_tm is not null and (tm-old_tm>15000 or step_m>60 or step_m>40*(tm-old_tm)/1000.0) then
      trips:='{}';old_tm:=tm;old_lat:=lat;old_lon:=lon;continue;
    end if;
    old_tm:=tm;old_lat:=lat;old_lon:=lon;
    next_trips:='{}';completed:=array[]::text[];
    for road in select * from conquest_internal.road_geometry g where g.catalog=p_catalog and
      (trips ? g.road_id or extensions.st_intersects(extensions.st_expand(g.path,0.004),
        extensions.st_setsrid(extensions.st_makepoint(lon,lat),4326))) order by ordinal loop
      select * into pos from conquest_internal.locate(road.path,lat,lon);
      trip:=trips->road.road_id;
      sx:=pi()/180*6371008.8*cos(radians(extensions.st_y(extensions.st_startpoint(road.path))));
      exit_m:=sqrt(power((lon-extensions.st_x(extensions.st_endpoint(road.path)))*sx,2)+
        power((lat-extensions.st_y(extensions.st_endpoint(road.path)))*sy,2));
      observations:=coalesce((trip->>'observations')::integer,0);
      reached:=coalesce((trip->>'exit')::boolean,false);
      if reached and observations>=3 and exit_m>12+acc and pos.progress_m>=pos.length_m-8 then
        completed:=array_append(completed,road.road_id);continue;
      end if;
      if pos.distance_m+acc>20 then continue;end if;
      if trip is null then
        if pos.progress_m>=-12+acc and pos.progress_m<=12-acc then
          next_trips:=next_trips||jsonb_build_object(road.road_id,jsonb_build_object('max',pos.progress_m,'observations',1,'exit',false));
        end if;
      elsif pos.progress_m>=(trip->>'max')::double precision-8 then
        max_progress:=greatest((trip->>'max')::double precision,pos.progress_m);
        if pos.progress_m>=pos.length_m+greatest(2,acc) and observations>=3 then
          completed:=array_append(completed,road.road_id);
        else
          reached:=reached or (pos.progress_m>=pos.length_m-acc and exit_m<=12-acc);
          next_trips:=next_trips||jsonb_build_object(road.road_id,
            jsonb_build_object('max',max_progress,'observations',observations+1,'exit',reached));
        end if;
      end if;
    end loop;
    trips:=next_trips;
    if cardinality(completed)=1 then completions:=completions||jsonb_build_array(
      jsonb_build_object('roadId',completed[1],'eventId',eid||':conquest:'||completed[1],'occurredMs',tm));end if;
  end loop;
  return completions;
end $$;

-- Transient proof -> trusted ledger. Still private: no client UID/time/proof claims are trusted by an API.
create function conquest_internal.submit_proof(
  p_user uuid,p_partition text,p_catalog text,p_event text,p_road text,p_occurred_ms bigint,
  p_samples jsonb,p_admitted_ms bigint
) returns jsonb language plpgsql set search_path='' as $$
declare proof_hash text; events jsonb; matched jsonb; result jsonb;
  detector constant text:='directed-road-v1';
begin
  if p_admitted_ms is null or p_admitted_ms<0 or p_samples is null or jsonb_typeof(p_samples)<>'array' or jsonb_array_length(p_samples) not between 3 and 2048
    then raise exception 'Invalid proof batch';end if;
  proof_hash:=encode(sha256(convert_to(p_samples::text,'UTF8')),'hex');
  -- Resolve prior immutable receipts before revalidation or the new-event deadline.
  if exists(select 1 from conquest_internal.receipts where user_id=p_user and partition=p_partition and event_id=p_event) then
    return conquest_internal.accept_verified(p_user,p_partition,p_catalog,p_event,p_road,p_occurred_ms,
      proof_hash,detector,p_admitted_ms);
  end if;
  events:=conquest_internal.replay_proof(p_catalog,p_samples);
  matched:=events->0;
  if jsonb_array_length(events)<>1 or matched->>'roadId' is distinct from p_road
    or matched->>'eventId' is distinct from p_event or (matched->>'occurredMs')::bigint is distinct from p_occurred_ms
    or (p_samples->-1->>'time')::bigint is distinct from p_occurred_ms then
    -- A final rejection is immutable too. Recheck after the shared scope lock to handle a competing submit.
    perform 1 from conquest_internal.worlds where partition=p_partition for update;
    if not found then raise exception 'Invalid partition';end if;
    if exists(select 1 from conquest_internal.receipts where user_id=p_user and partition=p_partition and event_id=p_event) then
      return conquest_internal.accept_verified(p_user,p_partition,p_catalog,p_event,p_road,p_occurred_ms,
        proof_hash,detector,p_admitted_ms);
    end if;
    result:=jsonb_build_object('eventId',p_event,'status','INVALID_PROOF');
    insert into conquest_internal.receipts values(p_user,p_partition,p_event,
      jsonb_build_object('catalog',p_catalog,'road',p_road,'occurred_ms',p_occurred_ms,
        'proof_hash',proof_hash,'detector',detector),result,
      p_admitted_ms);
    return result;
  end if;
  return conquest_internal.accept_verified(p_user,p_partition,p_catalog,p_event,p_road,p_occurred_ms,
    proof_hash,detector,p_admitted_ms);
end $$;

revoke all on all functions in schema conquest_internal from public,anon,authenticated;

-- gateway
create function conquest_internal.admission_now_ms() returns bigint
language sql volatile set search_path='' as $$ select floor(extract(epoch from clock_timestamp())*1000)::bigint $$;
create table conquest_internal.gateway_receipts (
  user_id uuid not null, partition text not null, event_id text not null,
  request_hash text not null check(request_hash ~ '^[a-f0-9]{64}$'),
  primary key(user_id,partition,event_id),
  foreign key(user_id,partition,event_id) references conquest_internal.receipts(user_id,partition,event_id)
);
alter table conquest_internal.gateway_receipts enable row level security;
revoke all on conquest_internal.gateway_receipts from public,anon,authenticated;
revoke all on function conquest_internal.admission_now_ms() from public,anon,authenticated;

-- Narrow privileged gateways only: derive UID from verified JWT, not request arguments.
create function public.conquest_select_team_v1(p_partition text,p_catalog text,p_team text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); active_catalog text; result text; membership conquest_internal.memberships%rowtype;
begin
  if uid is null then raise exception 'Authentication required';end if;
  select catalog into active_catalog from conquest_internal.worlds where partition=p_partition for update;
  if not found or active_catalog is distinct from p_catalog then raise exception 'Unavailable conquest catalog';end if;
  result:=conquest_internal.select_team(uid,p_partition,p_team,conquest_internal.admission_now_ms());
  select * into membership from conquest_internal.memberships where user_id=uid and partition=p_partition;
  return jsonb_build_object('protocol',1,'userId',uid::text,'partition',p_partition,'catalogVersion',p_catalog,
    'status',result,'teamId',membership.team_id,'selectedUtcMs',membership.selected_ms);
end $$;

-- Read-only membership recovery. Never creates a user, world or membership.
create function public.conquest_membership_v1(p_partition text,p_catalog text)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid(); active_catalog text; membership conquest_internal.memberships%rowtype;
begin
  if uid is null then raise exception 'Authentication required';end if;
  select catalog into active_catalog from conquest_internal.worlds where partition=p_partition;
  if not found or active_catalog is distinct from p_catalog then raise exception 'Unavailable conquest catalog';end if;
  select * into membership from conquest_internal.memberships where user_id=uid and partition=p_partition;
  return jsonb_build_object('protocol',1,'userId',uid::text,'partition',p_partition,'catalogVersion',p_catalog,
    'status',case when found then 'MEMBER' else 'NO_TEAM' end,
    'teamId',membership.team_id,'selectedUtcMs',membership.selected_ms);
end $$;

-- p_events is an array of immutable UTF-8 JSON strings. Hash the exact strings for queue ACK correlation.
create function conquest_internal.submit_checked(p_partition text,p_catalog text,p_events jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  uid uuid:=auth.uid(); active_catalog text; admitted bigint; item jsonb; body jsonb; raw text;
  bodies jsonb:='[]'; ids text[]:=array[]::text[]; results jsonb:='[]'; v_event_id text; v_request_hash text;
  saved_hash text; result jsonb; status text; row record;
begin
  if uid is null then raise exception 'Authentication required';end if;
  -- Provisional isolated-test bounds, to be measured/reviewed before release.
  if p_events is null or jsonb_typeof(p_events)<>'array' or jsonb_array_length(p_events) not between 1 and 20
    or octet_length(p_events::text)>1048576 then raise exception 'Invalid conquest batch';end if;
  -- Validate the entire envelope before writing any item. Unknown owner/clock fields are rejected.
  for item in select value from jsonb_array_elements(p_events) loop
    if jsonb_typeof(item)<>'string' then raise exception 'Expected immutable event JSON';end if;
    raw:=item#>>'{}';
    if octet_length(raw)>262144 then raise exception 'Conquest event too large';end if;
    begin body:=raw::jsonb; exception when others then raise exception 'Malformed conquest event';end;
    if jsonb_typeof(body)<>'object' or
      (select count(*) from jsonb_object_keys(body))<>4 or
      not (body ?& array['eventId','roadId','occurredMs','samples']) or
      jsonb_typeof(body->'eventId') is distinct from 'string' or
      jsonb_typeof(body->'roadId') is distinct from 'string' or
      jsonb_typeof(body->'occurredMs') is distinct from 'number' or
      (body->>'occurredMs') !~ '^(0|[1-9][0-9]*)$' or
      jsonb_typeof(body->'samples') is distinct from 'array' then raise exception 'Invalid conquest event fields';end if;
    v_event_id:=body->>'eventId';
    if length(v_event_id) not between 1 and 200 or length(btrim(v_event_id))=0 or length(btrim(body->>'roadId'))=0
      or jsonb_array_length(body->'samples') not between 3 and 2048 then raise exception 'Invalid conquest event bounds';end if;
    perform (body->>'occurredMs')::bigint;
    if v_event_id=any(ids) then raise exception 'Duplicate event in batch';end if;
    ids:=array_append(ids,v_event_id);
    bodies:=bodies||jsonb_build_array(body);
  end loop;
  select catalog into active_catalog from conquest_internal.worlds where partition=p_partition for update;
  -- Keep immutable retries readable after a catalog change. New old-version events are rejected by the ledger.
  if not found or not exists(select 1 from conquest_internal.catalogs where version=p_catalog)
    then raise exception 'Unavailable conquest catalog';end if;
  admitted:=conquest_internal.admission_now_ms();
  for row in select value,ordinality from jsonb_array_elements(p_events) with ordinality loop
    raw:=row.value#>>'{}';body:=bodies->(row.ordinality::integer-1);v_event_id:=body->>'eventId';
    v_request_hash:=encode(sha256(convert_to(raw,'UTF8')),'hex');
    select g.request_hash into saved_hash from conquest_internal.gateway_receipts g
      where g.user_id=uid and g.partition=p_partition and g.event_id=v_event_id;
    if found and saved_hash<>v_request_hash then
      result:=jsonb_build_object('status','CONFLICT');
    else
      if not found and exists(select 1 from conquest_internal.receipts
        where user_id=uid and partition=p_partition and event_id=v_event_id) then
        raise exception 'Receipt requires explicit gateway migration';
      end if;
      result:=conquest_internal.submit_proof(uid,p_partition,p_catalog,v_event_id,body->>'roadId',
        (body->>'occurredMs')::bigint,body->'samples',admitted);
      if (result->>'status') not in ('FUTURE','CONFLICT') then
        insert into conquest_internal.gateway_receipts values(uid,p_partition,v_event_id,v_request_hash) on conflict do nothing;
      end if;
    end if;
    status:=result->>'status';
    results:=results||jsonb_build_array(jsonb_build_object('eventId',v_event_id,'roadId',body->>'roadId',
      'occurredMs',(body->>'occurredMs')::bigint,'requestHash',v_request_hash,'status',status,
      'acknowledge',status not in ('FUTURE','CONFLICT'),'retryable',status='FUTURE'));
  end loop;
  return jsonb_build_object('protocol',1,'userId',uid::text,'partition',p_partition,'catalogVersion',p_catalog,
    'receivedUtcMs',admitted,'results',results);
end $$;

revoke all on function public.conquest_select_team_v1(text,text,text) from public,anon,authenticated;
revoke all on function conquest_internal.submit_checked(text,text,jsonb) from public,anon,authenticated;
revoke all on function public.conquest_membership_v1(text,text) from public,anon,authenticated;
grant execute on function public.conquest_select_team_v1(text,text,text) to authenticated;

grant execute on function public.conquest_membership_v1(text,text) to authenticated;

-- settlement
create table conquest_internal.settlement_scopes (
  partition text primary key references conquest_internal.worlds(partition),
  catalog text not null references conquest_internal.catalogs(version),
  started_ms bigint not null check(started_ms>=0),
  first_ms bigint not null check(first_ms>started_ms),
  last_ms bigint,
  revision bigint not null default 0 check(revision>=0),
  road_count integer not null check(road_count>0),
  unique(partition,catalog),
  check((revision=0 and last_ms is null) or (revision>0 and last_ms>=first_ms))
);
create table conquest_internal.settlement_runs (
  partition text not null, cutoff_ms bigint not null, catalog text not null,
  window_start_ms bigint not null, revision bigint not null check(revision>0),
  completed_ms bigint not null check(completed_ms>=cutoff_ms),
  primary key(partition,cutoff_ms), unique(partition,revision), unique(partition,cutoff_ms,catalog),
  foreign key(partition,catalog) references conquest_internal.settlement_scopes(partition,catalog),
  check(window_start_ms<cutoff_ms)
);
create table conquest_internal.settlement_roads (
  partition text not null, cutoff_ms bigint not null, catalog text not null, road_id text not null,
  previous_owner text references conquest_internal.teams(id), owner text references conquest_internal.teams(id),
  scores jsonb not null check(jsonb_typeof(scores)='object'),
  reason text not null check(reason in ('CAPTURED','RETAINED','TAKEN_OVER','TIE_RETAINED','TIE_NEUTRAL','NO_CONTRIBUTIONS')),
  primary key(partition,cutoff_ms,road_id),
  foreign key(partition,cutoff_ms,catalog) references conquest_internal.settlement_runs(partition,cutoff_ms,catalog),
  foreign key(catalog,road_id) references conquest_internal.roads(catalog,id)
);
alter table conquest_internal.settlement_scopes add foreign key(partition,last_ms)
  references conquest_internal.settlement_runs(partition,cutoff_ms);

create function conquest_internal.latest_noon_ms(p_ms bigint) returns bigint
language sql stable strict set search_path='' as $$
  select (extract(epoch from ((date_trunc('day',local_time)+interval '12 hours'
    -case when extract(hour from local_time)<12 then interval '1 day' else interval '0 day' end)
    at time zone 'Asia/Seoul'))*1000)::bigint
  from (select to_timestamp(p_ms/1000.0) at time zone 'Asia/Seoul' local_time) t
$$;

-- Operator-only initialization. S is explicit; first settlement is the first KST noon STRICTLY after S.
create function conquest_internal.initialize_settlement(p_partition text,p_started_ms bigint) returns void
language plpgsql set search_path='' as $$
declare active_catalog text; saved conquest_internal.settlement_scopes%rowtype; total integer;
begin
  if p_started_ms is null or p_started_ms<0 then raise exception 'Invalid conquest start';end if;
  select catalog into active_catalog from conquest_internal.worlds where partition=p_partition for update;
  if not found then raise exception 'Unavailable conquest world';end if;
  select * into saved from conquest_internal.settlement_scopes where partition=p_partition for update;
  if found then
    if saved.catalog<>active_catalog or saved.started_ms<>p_started_ms then raise exception 'Conquest scope already initialized';end if;
    return;
  end if;
  select count(*) into total from conquest_internal.roads where catalog=active_catalog;
  if total=0 then raise exception 'Empty conquest catalog';end if;
  insert into conquest_internal.settlement_scopes(partition,catalog,started_ms,first_ms,road_count)
    values(p_partition,active_catalog,p_started_ms,conquest_internal.latest_noon_ms(p_started_ms)+86400000,total);
end $$;

-- Same world lock/order as contribution admission. No user/API role may supply a cutoff or run settlement.
create function conquest_internal.settle_due(p_partition text,p_max_noons integer default 7)
returns jsonb language plpgsql set search_path='' as $$
declare active_catalog text; scope conquest_internal.settlement_scopes%rowtype; now_ms bigint;
  next_ms bigint; lower_ms bigint; processed integer:=0; inserted integer;
begin
  if p_max_noons is null or p_max_noons not between 1 and 31 then raise exception 'Invalid catch-up bound';end if;
  select catalog into active_catalog from conquest_internal.worlds where partition=p_partition for update;
  if not found then raise exception 'Unavailable conquest world';end if;
  -- Read clock only AFTER the submission/settlement serialization lock.
  now_ms:=conquest_internal.admission_now_ms();
  select * into scope from conquest_internal.settlement_scopes where partition=p_partition for update;
  if not found or scope.catalog<>active_catalog then raise exception 'Unavailable conquest settlement scope';end if;
  if now_ms is null or now_ms<scope.started_ms or now_ms<coalesce(scope.last_ms,scope.started_ms) then raise exception 'Invalid or backwards conquest clock';end if;
  if (select count(*) from conquest_internal.roads where catalog=scope.catalog)<>scope.road_count then
    raise exception 'Conquest catalog requires explicit migration';end if;
  if scope.last_ms is not null and (select count(*) from conquest_internal.settlement_roads
    where partition=p_partition and cutoff_ms=scope.last_ms)<>scope.road_count then
    raise exception 'Previous conquest settlement is incomplete';end if;
  next_ms:=coalesce(scope.last_ms+86400000,scope.first_ms);
  while next_ms<=now_ms and processed<p_max_noons loop
    lower_ms:=greatest(scope.started_ms,next_ms-129600000);
    insert into conquest_internal.settlement_runs values(p_partition,next_ms,scope.catalog,lower_ms,scope.revision+1,now_ms);
    with counts as (
      select road_id,team_id,count(*) points from conquest_internal.contributions
      where partition=p_partition and catalog=scope.catalog and occurred_ms>=lower_ms and occurred_ms<next_ms
      group by road_id,team_id
    ), ranked as (
      select *,max(points) over(partition by road_id) high from counts
    ), totals as (
      select road_id,jsonb_object_agg(team_id,points) scores,
        array_agg(team_id order by team_id) filter(where points=high) leaders from ranked group by road_id
    ), candidates as (
      select road.id road_id,old.owner previous_owner,coalesce(t.scores,'{}'::jsonb) scores,t.leaders,
        case when cardinality(t.leaders)=1 then t.leaders[1]
          when old.owner=any(t.leaders) then old.owner else null end owner
      from conquest_internal.roads road left join totals t on t.road_id=road.id
      left join conquest_internal.settlement_roads old on old.partition=p_partition and old.cutoff_ms=scope.last_ms and old.road_id=road.id
      where road.catalog=scope.catalog
    )
    insert into conquest_internal.settlement_roads
      select p_partition,next_ms,scope.catalog,road_id,previous_owner,owner,scores,
        case when leaders is null then 'NO_CONTRIBUTIONS'
          when cardinality(leaders)>1 then case when owner is null then 'TIE_NEUTRAL' else 'TIE_RETAINED' end
          when previous_owner is null then 'CAPTURED' when previous_owner=owner then 'RETAINED' else 'TAKEN_OVER' end
      from candidates;
    get diagnostics inserted=row_count;
    if inserted<>scope.road_count then raise exception 'Incomplete conquest settlement';end if;
    scope.last_ms:=next_ms;scope.revision:=scope.revision+1;
    update conquest_internal.settlement_scopes set last_ms=scope.last_ms,revision=scope.revision where partition=p_partition;
    processed:=processed+1;next_ms:=next_ms+86400000;
  end loop;
  return jsonb_build_object('processed',processed,'revision',scope.revision,'lastSettlementUtcMs',scope.last_ms,
    'nextSettlementUtcMs',next_ms,'hasMore',next_ms<=now_ms);
end $$;

-- A single statement snapshot, no settlement-on-read, no location proof or other users' contributions.
create function public.conquest_snapshot_v1(p_partition text,p_catalog text) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid(); scope conquest_internal.settlement_scopes%rowtype;
  membership conquest_internal.memberships%rowtype; roads jsonb; own_count bigint; owned_count bigint; own_latest bigint;
begin
  if uid is null then raise exception 'Authentication required';end if;
  select s.* into scope from conquest_internal.settlement_scopes s join conquest_internal.worlds w on w.partition=s.partition
    where s.partition=p_partition and s.catalog=p_catalog and w.catalog=s.catalog;
  if not found then raise exception 'Unavailable conquest snapshot';end if;
  if (select count(*) from conquest_internal.roads where catalog=p_catalog)<>scope.road_count
    or (scope.last_ms is not null and (select count(*) from conquest_internal.settlement_roads
      where partition=p_partition and cutoff_ms=scope.last_ms)<>scope.road_count) then raise exception 'Incomplete conquest snapshot';end if;
  select * into membership from conquest_internal.memberships where user_id=uid and partition=p_partition;
  select coalesce(jsonb_agg(jsonb_build_object('roadId',r.id,'ownerTeamId',s.owner,'previousOwnerTeamId',s.previous_owner,
      'scores',coalesce(s.scores,'{}'::jsonb),'reason',coalesce(s.reason,'INITIAL')) order by r.id),'[]'::jsonb),
    count(*) filter(where s.owner=membership.team_id) into roads,owned_count
    from conquest_internal.roads r left join conquest_internal.settlement_roads s
      on s.partition=p_partition and s.cutoff_ms=scope.last_ms and s.road_id=r.id where r.catalog=p_catalog;
  select count(*),max(occurred_ms) into own_count,own_latest from conquest_internal.contributions
    where user_id=uid and partition=p_partition and catalog=p_catalog and occurred_ms>=scope.started_ms;
  return jsonb_build_object('protocol',1,'userId',uid::text,'partition',p_partition,'catalogVersion',p_catalog,
    'revision',scope.revision,'generatedUtcMs',conquest_internal.admission_now_ms(),'startedUtcMs',scope.started_ms,
    'lastSettlementUtcMs',scope.last_ms,'nextSettlementUtcMs',coalesce(scope.last_ms+86400000,scope.first_ms),
    'summary',jsonb_build_object('teamId',membership.team_id,'contributionCount',own_count,'ownedRoadCount',owned_count,
      'lastUpdatedUtcMs',case when membership.team_id is null then null else greatest(membership.selected_ms,own_latest,scope.last_ms) end),
    'roads',roads);
end $$;

alter table conquest_internal.settlement_scopes enable row level security;
alter table conquest_internal.settlement_runs enable row level security;
alter table conquest_internal.settlement_roads enable row level security;
revoke all on conquest_internal.settlement_scopes,conquest_internal.settlement_runs,conquest_internal.settlement_roads from public,anon,authenticated;
revoke all on function conquest_internal.latest_noon_ms(bigint) from public,anon,authenticated;
revoke all on function conquest_internal.initialize_settlement(text,bigint) from public,anon,authenticated;
revoke all on function conquest_internal.settle_due(text,integer) from public,anon,authenticated;
revoke all on function public.conquest_snapshot_v1(text,text) from public,anon,authenticated;
grant execute on function public.conquest_snapshot_v1(text,text) to authenticated;

-- intake
create table conquest_internal.intake_control (
  partition text primary key check(partition in ('pleos','pleos-emulator')),
  paused boolean not null default true,
  revision bigint not null default 0 check(revision>=0),
  changed_ms bigint not null check(changed_ms>=0),
  reason text not null check(length(btrim(reason)) between 1 and 200),
  changed_by text not null
);
create table conquest_internal.intake_changes (
  partition text references conquest_internal.intake_control(partition),
  revision bigint not null check(revision>=0), paused boolean not null,
  changed_ms bigint not null check(changed_ms>=0), reason text not null,
  changed_by text not null, primary key(partition,revision)
);
insert into conquest_internal.intake_control(partition,changed_ms,reason,changed_by)
  select partition,floor(extract(epoch from clock_timestamp())*1000)::bigint,'Initially paused',session_user
  from (values('pleos'),('pleos-emulator')) partitions(partition);
insert into conquest_internal.intake_changes select partition,revision,paused,changed_ms,reason,changed_by
  from conquest_internal.intake_control;
alter table conquest_internal.intake_control enable row level security;
alter table conquest_internal.intake_changes enable row level security;
revoke all on conquest_internal.intake_control,conquest_internal.intake_changes from public,anon,authenticated;

create function conquest_internal.intake_status(p_partition text) returns jsonb
language plpgsql stable set search_path='' as $$
declare state conquest_internal.intake_control%rowtype;
begin
  select * into state from conquest_internal.intake_control where partition=p_partition;
  if not found then raise exception 'Unavailable conquest intake control';end if;
  return jsonb_build_object('partition',state.partition,'paused',state.paused,'revision',state.revision,
    'changedUtcMs',state.changed_ms,'reason',state.reason,'databaseRole',state.changed_by,
    'worldConfigured',exists(select 1 from conquest_internal.worlds where partition=p_partition));
end $$;

-- INVOKER, no client grant. Compare-and-set prevents a stale operator from undoing a newer pause.
create function conquest_internal.set_intake(p_partition text,p_paused boolean,p_expected_revision bigint,p_reason text)
returns jsonb language plpgsql set search_path='' as $$
declare state conquest_internal.intake_control%rowtype; changed bigint;
begin
  if p_paused is null or p_expected_revision is null or p_expected_revision<0 or p_reason is null
    or length(btrim(p_reason)) not between 1 and 200 then raise exception 'Invalid intake operation';end if;
  perform 1 from conquest_internal.worlds where partition=p_partition for update;
  if not found then raise exception 'Unavailable conquest world';end if;
  select * into state from conquest_internal.intake_control where partition=p_partition for update;
  if not found then raise exception 'Unavailable conquest intake control';end if;
  if state.revision<>p_expected_revision then raise exception 'Intake revision changed; read current state';end if;
  if state.paused=p_paused then return conquest_internal.intake_status(p_partition);end if;
  changed:=floor(extract(epoch from clock_timestamp())*1000)::bigint;
  update conquest_internal.intake_control set paused=p_paused,revision=state.revision+1,
    changed_ms=changed,reason=btrim(p_reason),changed_by=session_user where partition=p_partition;
  insert into conquest_internal.intake_changes values(p_partition,state.revision+1,p_paused,changed,btrim(p_reason),session_user);
  return conquest_internal.intake_status(p_partition);
end $$;
revoke all on function conquest_internal.intake_status(text) from public,anon,authenticated;
revoke all on function conquest_internal.set_intake(text,boolean,bigint,text) from public,anon,authenticated;

-- The verified gateway was created private from the start; publish only the intake wrapper.

revoke all on function conquest_internal.submit_checked(text,text,jsonb) from public,anon,authenticated;
create function public.conquest_submit_v1(p_partition text,p_catalog text,p_events jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare paused boolean;
begin
  if auth.uid() is null then raise exception 'Authentication required';end if;
  perform 1 from conquest_internal.worlds where partition=p_partition for update;
  if not found then raise exception 'Unavailable conquest world';end if;
  select c.paused into paused from conquest_internal.intake_control c where c.partition=p_partition for update;
  if not found or paused then
    raise sqlstate 'PT503' using message='Conquest submissions temporarily unavailable';
  end if;
  return conquest_internal.submit_checked(p_partition,p_catalog,p_events);
end $$;
revoke all on function public.conquest_submit_v1(text,text,jsonb) from public,anon,authenticated;
grant execute on function public.conquest_submit_v1(text,text,jsonb) to authenticated;
notify pgrst,'reload schema';
commit;
